<?php require_once "../config/auth.php";require_admin();$p=db();$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$id=(int)$_POST["id"];$a=$_POST["action"];$p->beginTransaction();try{$q=$p->prepare("SELECT * FROM withdrawals WHERE id=? FOR UPDATE");$q->execute([$id]);$w=$q->fetch();if(!$w||$w["status"]!=="pending")throw new Exception("Already reviewed.");if($a==="approve")$p->prepare("UPDATE withdrawals SET status='approved',reviewed_at=NOW() WHERE id=?")->execute([$id]);else{$p->prepare("UPDATE users SET balance=balance+? WHERE id=?")->execute([$w["amount"],$w["user_id"]]);$p->prepare("UPDATE withdrawals SET status='rejected',reviewed_at=NOW() WHERE id=?")->execute([$id]);$p->prepare("INSERT INTO transactions(user_id,type,amount,description) VALUES(?,'refund',?,'Withdrawal rejected')")->execute([$w["user_id"],$w["amount"]]);}$p->commit();$msg="Updated.";}catch(Exception $e){$p->rollBack();$msg=$e->getMessage();}}$rows=$p->query("SELECT w.*,u.username FROM withdrawals w JOIN users u ON u.id=w.user_id ORDER BY w.id DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../public/style.css"></head><body><main><h1>Withdrawals</h1><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="table"><table><tr><th>ID</th><th>User</th><th>Amount</th><th>Method</th><th>Account</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=e($r["username"])?></td><td>৳<?=$r["amount"]?></td><td><?=e($r["method"])?></td><td><?=e($r["account"])?></td><td><?=$r["status"]?></td><td><?php if($r["status"]==="pending"):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r["id"]?>"><button name="action" value="approve">Approve</button><button name="action" value="reject">Reject</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></main></body></html>